61	
62	type FloatingActionButtonAndPopoverProps = {
63	    /* Callback function when the menu is shown */
64	    onShowCreateMenu?: () => void;
65	
66	    /* Callback function before the menu is hidden */
67	    onHideCreateMenu?: () => void;
68	
69	    /* If the tooltip is allowed to be shown */
