[metadata] {"type": "text", "file": {"filePath": "/app/expensify/src/pages/home/sidebar/FloatingActionButtonAndPopover.tsx", "content": "import {useIsFocused} from '@react-navigation/native';\nimport {Str} from 'expensify-common';\nimport type {ImageContentFit} from 'expo-image';\nimport type {ForwardedRef} from 'react';\nimport React, {useCallback, useContext, useEffect, useImperativeHandle, useMemo, useRef, useState} from 'react';\nimport {View} from 'react-native';\nimport type {OnyxCollection, OnyxEntry} from 'react-native-onyx';\nimport ConfirmModal from '@components/ConfirmModal';\nimport {DelegateNoAccessContext} from '@components/DelegateNoAccessModalProvider';\nimport FloatingActionButton from '@components/FloatingActionButton';\nimport * as Expensicons from '@components/Icon/Expensicons';\nimport type {PopoverMenuItem} from '@components/PopoverMenu';\nimport PopoverMenu from '@components/PopoverMenu';\nimport useCurrentUserPersonalDetails from '@hooks/useCurrentUserPersonalDetails';\nimport useLocalize from '@hooks/useLocalize';\nimport useNetwork from '@hooks/useNetwork';\nimport useOnyx from '@hooks/useOnyx';\nimport usePermissions from '@hooks/usePermissions';\nimport usePrevious from '@hooks/usePrevious';\nimport useReportIsArchived from '@hooks/useReportIsArchived';\nimport useResponsiveLayout from '@hooks/useResponsiveLayout';\nimport useTheme from '@hooks/useTheme';\nimport useThemeStyles from '@hooks/useThemeStyles';\nimport useWindowDimensions from '@hooks/useWindowDimensions';\nimport {startDistanceRequest, startMoneyRequest} from '@libs/actions/IOU';\nimport {openOldDotLink} from '@libs/actions/Link';\nimport {navigateToQuickAction} from '@libs/actions/QuickActionNavigation';\nimport {createNewReport, startNewChat} from '@libs/actions/Report';\nimport {isAnonymousUser} from '@libs/actions/Session';\nimport {startTestDrive} from '@libs/actions/Tour';\nimport getIconForAction from '@libs/getIconForAction';\nimport interceptAnonymousUser from '@lib